from itertools import combinations

def P(n):
    pts = {(0,0)}
    for k in range(n+1):
        r2 = 2**k
        for x in range(-int(r2**0.5)-2, int(r2**0.5)+3):
            for y in range(-int(r2**0.5)-2, int(r2**0.5)+3):
                if x*x + y*y == r2:
                    pts.add((x,y))
    return pts

def is_square(p1,p2,p3,p4):
    pts = [p1,p2,p3,p4]
    dists = []
    for i in range(4):
        for j in range(i+1,4):
            dx = pts[i][0]-pts[j][0]
            dy = pts[i][1]-pts[j][1]
            dists.append(dx*dx+dy*dy)
    dists.sort()
    return dists[0]>0 and dists[0]==dists[1]==dists[2]==dists[3] and dists[4]==dists[5] and dists[4]==2*dists[0]

def square_center(p1,p2,p3,p4):
    pts = [p1,p2,p3,p4]
    # find center: average of vertices
    cx = sum(p[0] for p in pts)/4
    cy = sum(p[1] for p in pts)/4
    return (cx, cy)

for n in range(8):
    pts = list(P(n))
    origin_squares = 0  # has origin as vertex
    centered_origin = 0  # centered at origin, no origin vertex
    other = 0
    for combo in combinations(pts, 4):
        if is_square(*combo):
            c = square_center(*combo)
            has_origin = (0,0) in combo
            centered_at_origin = (c == (0.0, 0.0))
            if has_origin:
                origin_squares += 1
            elif centered_at_origin:
                centered_origin += 1
            else:
                other += 1
                print(f"  n={n} OTHER: {combo} center={c}")
    print(f"n={n}: origin_vertex={origin_squares}, centered_origin={centered_origin}, other={other}, total={origin_squares+centered_origin+other}")
